  boat:{seatIn:true,name:"Rowboat",seat:true,draw:(x,y,w,h)=>`<path d="M${x+14} ${y+h/2}C${x+30} ${y+14} ${x+w-60} ${y+16} ${x+w-14} ${y+h/2}C${x+w-60} ${y+h-16} ${x+30} ${y+h-14} ${x+14} ${y+h/2}Z" fill="#f8fafc" stroke="#0f766e" stroke-width="5" filter="url(#sh)"/><rect x="${x+w/2-34}" y="${y+h/2-22}" width="10" height="44" fill="#a77745"/><rect x="${x+w/2+20}" y="${y+h/2-22}" width="10" height="44" fill="#a77745"/>`},
