  angelfountain:{name:"Angel of the Waters",seat:false,draw:(x,y)=>{const cx=x+50,cy=y+50;return `<circle cx="${cx}" cy="${cy}" r="45" fill="#cfc6b4" filter="url(#sh)"/><circle cx="${cx}" cy="${cy}" r="38" fill="url(#g-pool)"/><circle cx="${cx}" cy="${cy}" r="18" fill="#d9d1c0"/><circle cx="${cx}" cy="${cy}" r="12" fill="#b9e3f5"/><path d="M${cx} ${cy-14}l-20 -10q8 10 14 12zM${cx} ${cy-14}l20 -10q-8 10 -14 12z" fill="#7aa38f"/><circle cx="${cx}" cy="${cy-6}" r="7" fill="#6f9886"/><circle cx="${cx}" cy="${cy-14}" r="4" fill="#6f9886"/>`}},
  bowbridge:{name:"Bow Bridge",seat:true,draw:(x,y,w,h)=>{const v=h>w;let s=`<rect x="${x+(v?14:0)}" y="${y+(v?0:14)}" width="${v?w-28:w}" height="${v?h:h-28}" fill="#e8dfcd" filter="url(#sh)"/>`;
    const n=v?Math.round(h/20):Math.round(w/20);for(let i=0;i<=n;i++){s+=v?`<path d="M${x+14} ${y+i*20}h${w-28}" stroke="#c9bda6" stroke-width="2"/>`:`<path d="M${x+i*20} ${y+14}v${h-28}" stroke="#c9bda6" stroke-width="2"/>`;}
    s+=v?`<path d="M${x+14} ${y}V${y+h}M${x+w-14} ${y}V${y+h}" stroke="#7d8f96" stroke-width="6"/>${Array.from({length:Math.round(h/14)},(_,i)=>`<circle cx="${x+14}" cy="${y+7+i*14}" r="3" fill="#5f7178"/><circle cx="${x+w-14}" cy="${y+7+i*14}" r="3" fill="#5f7178"/>`).join("")}`
       :`<path d="M${x} ${y+14}H${x+w}M${x} ${y+h-14}H${x+w}" stroke="#7d8f96" stroke-width="6"/>${Array.from({length:Math.round(w/14)},(_,i)=>`<circle cx="${x+7+i*14}" cy="${y+14}" r="3" fill="#5f7178"/><circle cx="${x+7+i*14}" cy="${y+h-14}" r="3" fill="#5f7178"/>`).join("")}`;return s;}},
  sailboat:{name:"Model Sailboat",seat:false,draw:(x,y)=>`<ellipse cx="${x+52}" cy="${y+58}" rx="30" ry="9" fill="#000" opacity=".14"/><path d="M${x+22} ${y+56}h56l-10 12H${x+32}z" fill="#9b4a2c"/><path d="M${x+50} ${y+14}v42" stroke="#5b3c22" stroke-width="3"/><path d="M${x+52} ${y+16}l24 36H${x+52}z" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1.5"/><path d="M${x+48} ${y+22}l-20 30h20z" fill="#e11d48"/>`},
  lamppost:{name:"Lamppost",seat:false,draw:(x,y)=>`<circle cx="${x+50}" cy="${y+50}" r="26" fill="#fde68a" opacity=".35"/><circle cx="${x+54}" cy="${y+55}" r="13" fill="#000" opacity=".16"/><rect x="${x+39}" y="${y+39}" width="22" height="22" rx="4" fill="#1f2937" filter="url(#sh)"/><rect x="${x+43}" y="${y+43}" width="14" height="14" rx="2" fill="#fef3c7"/><circle cx="${x+50}" cy="${y+50}" r="3.5" fill="#1f2937"/>`},
  swanboat:{seatIn:true,name:"Swan Boat",seat:true,draw:(x,y,w,h)=>`<g filter="url(#sh)"><rect x="${x+16}" y="${y+22}" width="${w-60}" height="${h-44}" rx="20" fill="#2f855a"/><rect x="${x+24}" y="${y+30}" width="${w-76}" height="${h-60}" rx="12" fill="#68d391"/></g>${[0,1,2].map(i=>`<rect x="${x+34+i*((w-100)/2)}" y="${y+32}" width="8" height="${h-64}" rx="3" fill="#f8fafc"/>`).join("")}<path d="M${x+w-48} ${y+30}q30 -4 30 20q0 22 -30 20z" fill="#f8fafc" stroke="#cbd5e1" stroke-width="2"/><path d="M${x+w-28} ${y+50}q14 -18 4 -30q-6 -6 -10 2" fill="none" stroke="#f8fafc" stroke-width="7" stroke-linecap="round"/><path d="M${x+w-36} ${y+18}l-10 -2 6 6z" fill="#f59e0b"/>`},
  willow:{name:"Willow",seat:false,draw:(x,y)=>{const cx=x+50,cy=y+50;let s=`<ellipse cx="${cx+6}" cy="${cy+8}" rx="44" ry="40" fill="#000" opacity=".16"/><circle cx="${cx}" cy="${cy}" r="42" fill="#7fae4e"/>`;for(let i=0;i<16;i++){const a=i*Math.PI/8;s+=`<path d="M${cx+8*Math.cos(a)} ${cy+8*Math.sin(a)}Q${cx+30*Math.cos(a+.3)} ${cy+30*Math.sin(a+.3)} ${cx+40*Math.cos(a)} ${cy+40*Math.sin(a)}" stroke="#9cc969" stroke-width="4" fill="none" stroke-linecap="round"/>`;}return s+`<circle cx="${cx}" cy="${cy}" r="9" fill="#6d9c41"/>`;}},
