  projector:{name:"Star Projector",seat:false,draw:(x,y)=>`<circle cx="${x+50}" cy="${y+50}" r="34" fill="#1e293b" filter="url(#sh)"/><circle cx="${x+50}" cy="${y+50}" r="22" fill="#334155"/>${Array.from({length:10},(_,i)=>{const a=i*Math.PI/5;return `<circle cx="${x+50+15*Math.cos(a)}" cy="${y+50+15*Math.sin(a)}" r="3.4" fill="#93c5fd"/>`}).join("")}<circle cx="${x+50}" cy="${y+50}" r="6" fill="#fde68a"/>`},
  teslacoil:{name:"Tesla Coil",seat:false,draw:(x,y)=>`<circle cx="${x+50}" cy="${y+50}" r="40" fill="#e5e7eb" stroke="#94a3b8" stroke-width="3" filter="url(#sh)"/><circle cx="${x+50}" cy="${y+50}" r="22" fill="#cbd5e1"/><circle cx="${x+50}" cy="${y+50}" r="14" fill="#b45309"/><circle cx="${x+50}" cy="${y+50}" r="9" fill="#e2e8f0" stroke="#64748b" stroke-width="2"/><path d="M${x+60} ${y+40}l10 -8 -4 8 10 -6M${x+40} ${y+60}l-10 8 4 -8 -10 6" stroke="#8b5cf6" stroke-width="2.4" fill="none" stroke-linejoin="round"/>`},
  pendulum:{name:"Foucault Pendulum",seat:false,draw:(x,y)=>`<circle cx="${x+50}" cy="${y+50}" r="44" fill="#a1866b" filter="url(#sh)"/><circle cx="${x+50}" cy="${y+50}" r="38" fill="#e7dcc6"/>${Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<circle cx="${x+50+33*Math.cos(a)}" cy="${y+50+33*Math.sin(a)}" r="2.5" fill="#7c5f45"/>`}).join("")}<path d="M${x+28} ${y+72}L${x+72} ${y+28}" stroke="#c8b898" stroke-width="2"/><circle cx="${x+58}" cy="${y+42}" r="9" fill="#b8892f" stroke="#7c5c1e" stroke-width="2"/>`},
