  birdcage:{seatIn:true,name:"Birdcage Elevator",seat:true,draw:(x,y)=>`<rect x="${x+14}" y="${y+14}" width="72" height="72" rx="6" fill="#7a5a2e" filter="url(#sh)"/><rect x="${x+20}" y="${y+20}" width="60" height="60" rx="4" fill="#d9c8a3"/>${[30,40,50,60,70].map(a=>`<path d="M${x+a} ${y+20}V${y+80}" stroke="#8a6a35" stroke-width="2.4"/>`).join("")}<path d="M${x+20} ${y+50}H${x+80}" stroke="#8a6a35" stroke-width="2.4"/><circle cx="${x+50}" cy="${y+50}" r="10" fill="none" stroke="#b8892f" stroke-width="3"/>`},
  staircase:{name:"Grand Staircase",seat:false,draw:(x,y,w,h)=>{let s=`<rect x="${x+8}" y="${y+8}" width="${w-16}" height="${h-16}" rx="4" fill="#9c2f2f" filter="url(#sh)"/>`;const n=Math.round((h-16)/12);for(let i=0;i<n;i++)s+=`<path d="M${x+8} ${y+8+i*12}H${x+w-8}" stroke="#7a2424" stroke-width="2"/>`;return s+`<path d="M${x+12} ${y+8}V${y+h-8}M${x+w-12} ${y+8}V${y+h-8}" stroke="#c9a25a" stroke-width="5"/>`;}},
  gazebo:{name:"Gazebo",seat:true,draw:(x,y)=>{const cx=x+50,cy=y+50;let p="";for(let i=0;i<8;i++){const a=i*Math.PI/4+Math.PI/8;p+=`${i?"L":"M"}${cx+42*Math.cos(a)} ${cy+42*Math.sin(a)}`;}return `<path d="${p}Z" fill="#f4efe4" stroke="#b9ad96" stroke-width="3" filter="url(#sh)"/>${Array.from({length:8},(_,i)=>{const a=i*Math.PI/4+Math.PI/8;return `<path d="M${cx} ${cy}L${cx+42*Math.cos(a)} ${cy+42*Math.sin(a)}" stroke="#d8cfbd" stroke-width="2"/>`}).join("")}<circle cx="${cx}" cy="${cy}" r="8" fill="#5f8c7d"/>`;}},
  palm:{name:"Palm Tree",seat:false,draw:(x,y)=>{const cx=x+50,cy=y+50;let s=`<ellipse cx="${cx+6}" cy="${cy+8}" rx="38" ry="34" fill="#000" opacity=".15"/>`;for(let i=0;i<7;i++){const a=i*2*Math.PI/7;s+=`<path d="M${cx} ${cy}Q${cx+30*Math.cos(a+.35)} ${cy+30*Math.sin(a+.35)} ${cx+44*Math.cos(a)} ${cy+44*Math.sin(a)}" stroke="#3f8f4a" stroke-width="11" fill="none" stroke-linecap="round"/><path d="M${cx} ${cy}Q${cx+30*Math.cos(a+.35)} ${cy+30*Math.sin(a+.35)} ${cx+44*Math.cos(a)} ${cy+44*Math.sin(a)}" stroke="#7cc46f" stroke-width="2.5" fill="none"/>`;}return s+`<circle cx="${cx}" cy="${cy}" r="8" fill="#8a5a2b"/>`;}},
